effect.shader:
const float LARGURA_MAX = 720.0;

// Os sliders do Sapphire chegam em ponto fixo 16.16.
float fixo(float v) { return floor(v * 65536.0 + 0.5) / 65536.0; }

ivec2 gT;          // o buffer
ivec2 gN;          // a camada do AE dentro dele, em px
ivec2 gInicio;     // o canto da camada no buffer
float gEscala;     // a prévia reduzida (o Source Blur é em px da composição)

void preparar() {
    gT = textureSize(inputImg, 0);
    gN = clamp(ivec2(floor(max(acCamada, vec2(0.001)) * vec2(gT) + 0.5)), ivec2(1), gT);
    gInicio = (gT - gN) / 2;
    gEscala = acEscalaDePixel > 0.0 ? acEscalaDePixel : 1.0;
}

int espelhar(int i, int n) {
    if (i >= 0 && i < n) return i;
    int p = 2 * n;
    i = i - (i / p) * p; if (i < 0) i += p;
    return i < n ? i : p - 1 - i;
}

ivec2 naCamada(ivec2 q) { return gInicio + ivec2(espelhar(q.x, gN.x), espelhar(q.y, gN.y)); }

vec4 guardar(float f) {
    uint b = floatBitsToUint(f);
    return vec4(float(b & 255u), float((b >> 8u) & 255u), float((b >> 16u) & 255u), float(b >> 24u)) / 255.0;
}

float lido(vec4 c) {
    uvec4 b = uvec4(floor(c * 255.0 + 0.5));
    return uintBitsToFloat(b.r | (b.g << 8u) | (b.b << 16u) | (b.a << 24u));
}

// Input Opacity (medido): Normal (1) usa a cor pré-multiplicada; All Opaque (0) e As Premult (2), a reta.
vec3 entrada(ivec2 p) {
    vec4 s = texelFetch(inputImg, p, 0);
    return inputOpacity == 1 ? s.rgb * s.a : s.rgb;
}

float monochrome(vec3 c) { return (0.3125 * c.r + 0.5 * c.g) + 0.1875 * c.b; }

// Medido: o Source Blur do AE já é a largura em px (subpixel ligado de fábrica no plugin).
float larguraPx() { return clamp(fixo(sourceBlur) * gEscala, 0.0, LARGURA_MAX); }

/** Uma das três caixas de um eixo (a conta do S_GlowAura): a que cresce leva as pontas com a fração. */
float caixa(ivec2 q, bool emX, int qual, bool deA) {
    float w = larguraPx();
    int a = int(floor(w));
    float f = w - float(a);
    int r = (a + 2 - qual) / 3;
    bool cresce = f > 0.0 && a - (a / 3) * 3 == qual;
    float soma = 0.0;
    for (int d = -r; d <= r; d++) {
        ivec2 p = naCamada(q + (emX ? ivec2(d, 0) : ivec2(0, d)));
        soma += lido(deA ? texelFetch(ga, p, 0) : texelFetch(gb, p, 0));
    }
    float n = float(2 * r + 1);
    if (!cresce) return soma / n;
    ivec2 e = naCamada(q - (emX ? ivec2(r + 1, 0) : ivec2(0, r + 1)));
    ivec2 g = naCamada(q + (emX ? ivec2(r + 1, 0) : ivec2(0, r + 1)));
    float pontas = deA ? lido(texelFetch(ga, e, 0)) + lido(texelFetch(ga, g, 0)) : lido(texelFetch(gb, e, 0)) + lido(texelFetch(gb, g, 0));
    return soma * ((1.0 - f) / n + f / (n + 2.0)) + pontas * (f / (n + 2.0));
}

void main() {
    preparar();
    ivec2 t = min(ivec2(floor(acScreenNorm * vec2(gT))), gT - ivec2(1));
    ivec2 q = t - gInicio;
    bool fora = any(lessThan(q, ivec2(0))) || any(greaterThanEqual(q, gN));

    if (acPass == 0) { fragColor = fora ? vec4(0.0) : guardar(monochrome(entrada(t))); return; }
    if (acPass <= 6) {
        float c = fora ? 0.0 : caixa(q, acPass <= 3, (acPass - 1) - ((acPass - 1) / 3) * 3, (acPass & 1) == 1);
        fragColor = guardar(c);
        return;
    }

    vec4 s = texelFetch(inputImg, t, 0);
    if (fora) { fragColor = s; return; }

    float bw = lido(texelFetch(ga, t, 0)) * fixo(sourceScale);
    vec3 ph = fixo(phaseStart) + vec3(fixo(phaseRed), fixo(phaseGreen), fixo(phaseBlue)) + fixo(phaseSpeed) * acTime;
    // polar_to_xy(dir / 360, mag); o ângulo do AE chega com o sinal trocado
    float ang = -fixo(stripeDir) * 0.017453292519943295;
    vec2 grad = fixo(stripeMag) * vec2(cos(ang), sin(ang));
    // xy do Sapphire: −1..1 na largura da camada, y para cima (a linha 0 do buffer é o topo, de pé é a base)
    float meia = float(gN.x) * 0.5;
    float linha = acEntradaDePe == 1 ? float(gN.y - 1 - q.y) : float(q.y);
    vec2 xy = vec2((float(q.x) + 0.5 - meia) / meia, (float(gN.y) * 0.5 - (linha + 0.5)) / meia);
    vec3 fq = fixo(freqColors) * vec3(fixo(freqRed), fixo(freqGreen), fixo(freqBlue));
    vec3 c = (0.5 + 0.5 * sin(6.2831853 * (fq * (bw + dot(xy, grad) - ph)))) * fixo(brightness) * (floor(color.rgb * 255.0 + 0.5) / 255.0);
    float lum = monochrome(c);
    vec3 pic = lum + (c - lum) * fixo(saturation);
    float k = mix(1.0, min(1.0, bw * fixo(scaleBySrcAmp)), fixo(scaleBySource));
    vec3 o = pic * k + fixo(offset);
    o = mix(o, entrada(t), fixo(mixWithSource));

    // Output Opacity (medido): Copy From Input = clip(saída) como cor reta com o alfa da fonte; All Opaque, opaco
    float a = outputOpacity == 0 ? 1.0 : s.a;
    fragColor = vec4(floor(clamp(o, 0.0, 1.0) * 255.0 + 0.5) / 255.0, a);
}
